//! Stage 0 semantic baseline: consistency of the golden fixtures for `ccut-timeline::motion` with out-of-order sampling.
//!
//! The fixtures live in `tests/fixtures/motion/`, are generated by this file, and are also verified bit-for-bit by this file.
//! Regenerate with: `CCUT_UPDATE_GOLDEN=1 cargo test -p ccut-timeline --test motion_baseline`.
//!
//! Comparison strategy: **byte-for-byte comparison of the serialised text**, with no epsilon. The output of `to_string_pretty`
//! (ryu shortest round-trip representation plus BTreeMap key order) is itself deterministic, so byte-for-byte comparison is the true
//! "bit-for-bit unchanged" check, and it does not depend on the parse direction setting.
//!
//! Sampling reads the built-in preset JSON. A constant with 17 significant digits (`timeline.loop.elSway3d`'s
//! `0.9659258262890683`) can only be read accurately with correct rounding. `core/Cargo.toml` enables `float_roundtrip` for
//! serde_json at the workspace level, so `-p ccut-timeline` run on its own, `--workspace`, and the Web
//! wasm all read the same double, and there is only one golden. The guard for the parse direction lives in
//! `ccut-motion/tests/float_parse.rs`.

use std::collections::BTreeMap;
use std::path::PathBuf;

use serde_json::{Value, json};
use timeline::motion::{
    AnimationPartUnit, AnimationPose, TextAnimationFrame, resolve_animation_pose,
    resolve_text_animation, split_animation_parts, summarize_animation,
};
use timeline::schema::{
    Animation, AnimationSlot, ENTER_PRESETS, EXIT_LEGACY_PRESETS, EXIT_PRESETS, LOOP_PRESETS,
};

// ── Fixed sampling window ─────────────────────────────────────────────────────
// start=1.0 / end=5.0 / projectEnd=10.0 / fps=30: lifetime 4s, half=2s;
// the default durations of all built-in presets (0.30..0.90) are never squeezed by `half`, so the entrance,
// idle loop and exit segments all really appear within the window.
const START: f64 = 1.0;
const END: f64 = 5.0;
const PROJECT_END: f64 = 10.0;
const FPS: f64 = 30.0;

/// The exit-recipe table is the document's closed set of exit values (the same table since round 156; `preset_lists_frozen`
/// checks it against the registry). `sink` and `shrink` are both mirror targets of `rise` and `pop`, and can also be written explicitly into the document.
const EXIT_PRESET_IDS: &[&str] = EXIT_PRESETS;

/// 0.1 compatibility names: an exit slot reads them in as valid but they have no exit recipe, so writing one into the exit slot should produce no exit at all.
/// `bounce` has no exit recipe of its own (a reversed bounce has no design-spec entry); when following an entrance, its exit is derived through
/// `mirror: "rise"` (2026-08-30). `drop` has had an exit of the same name since 2026-09-05
/// (design spec stomp), so it is no longer listed here.
const EXIT_ONLY_IN_SCHEMA: &[&str] = EXIT_LEGACY_PRESETS;

/// Local offset grid (seconds) covering [start, end]. Dense at the start and end, sparse in the middle,
/// so that it pins down the entrance curve, the idle-loop envelope and the exit curve at the same time.
const LOCAL_GRID: &[f64] = &[
    0.0, 0.1, 0.2, 0.3, 0.45, 0.6, 0.9, 1.2, 2.0, 2.8, 3.4, 3.6, 3.8, 3.9, 4.0,
];

/// Progress points when `dur = 0.4` is explicit (exactly 12 frames at 30 fps): 0/25/50/75/100%
/// all fall on the frame grid, so progress maps one-to-one onto the quantised time.
const PROGRESS_DUR: f64 = 0.4;
const PROGRESS_POINTS: &[f64] = &[0.0, 0.25, 0.5, 0.75, 1.0];

const INTENSITIES: &[f64] = &[0.5, 1.0];

fn fixture_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/motion")
}

fn updating() -> bool {
    std::env::var_os("CCUT_UPDATE_GOLDEN").is_some_and(|value| !value.is_empty())
}

/// Writes out, or compares bit-for-bit against, the golden. `serde_json` does not enable `preserve_order`, so `Map` is
/// a `BTreeMap`, and key order is naturally stable.
fn assert_golden(name: &str, actual: &Value) {
    let path = fixture_dir().join(name);
    let mut text = serde_json::to_string_pretty(actual).expect("序列化 golden");
    text.push('\n');
    if updating() {
        std::fs::create_dir_all(fixture_dir()).expect("创建 fixtures/motion");
        std::fs::write(&path, &text).expect("写入 golden");
        return;
    }
    let expected = std::fs::read_to_string(&path).unwrap_or_else(|error| {
        panic!(
            "读取 {} 失败：{error}；用 CCUT_UPDATE_GOLDEN=1 重生成",
            path.display()
        )
    });
    if expected == text {
        return;
    }
    let (line, want, got) = expected
        .lines()
        .zip(text.lines())
        .enumerate()
        .find(|(_, (a, b))| a != b)
        .map(|(index, (a, b))| (index + 1, a.to_owned(), b.to_owned()))
        .unwrap_or_else(|| {
            (
                expected.lines().count().min(text.lines().count()) + 1,
                format!("<{} 行>", expected.lines().count()),
                format!("<{} 行>", text.lines().count()),
            )
        });
    panic!(
        "{} 与当前实现不一致（第 {line} 行）：\n  golden: {want}\n  实得:   {got}\n\
         这是语义变更，必须先确认再用 CCUT_UPDATE_GOLDEN=1 重生成。",
        path.display()
    );
}

fn slot(preset: &str) -> AnimationSlot {
    AnimationSlot {
        preset: preset.to_owned(),
        preset_version: Some(1),
        dur: None,
        delay: None,
        intensity: None,
        ease: None,
        stagger: None,
        stagger_from: None,
        period: None,
        phase: None,
        seed: None,
    }
}

fn with_intensity(mut slot: AnimationSlot, intensity: f64) -> AnimationSlot {
    slot.intensity = Some(intensity);
    slot
}

fn animation(
    enter: Option<AnimationSlot>,
    exit: Option<AnimationSlot>,
    r#loop: Option<AnimationSlot>,
) -> Animation {
    Animation {
        enter,
        exit,
        r#loop,
    }
}

fn pose_json(pose: AnimationPose) -> Value {
    json!({
        "opacity": pose.opacity,
        "dx": pose.dx,
        "dy": pose.dy,
        "scaleX": pose.scale_x,
        "scaleY": pose.scale_y,
        "rotation": pose.rotation,
        "blur": pose.blur,
        "reveal": pose.reveal,
    })
}

fn summary_json(animation: &Animation) -> Value {
    Value::Array(
        summarize_animation(animation)
            .into_iter()
            .map(|item| {
                json!({
                    "kind": format!("{:?}", item.kind),
                    "preset": item.preset,
                    "derived": item.derived,
                })
            })
            .collect(),
    )
}

/// Serialises the animation and strips `null` fields: the fixture records only the slot parameters that were actually set.
fn animation_json(animation: &Animation) -> Value {
    fn prune(value: Value) -> Value {
        match value {
            Value::Object(map) => Value::Object(
                map.into_iter()
                    .filter(|(_, value)| !value.is_null())
                    .map(|(key, value)| (key, prune(value)))
                    .collect(),
            ),
            other => other,
        }
    }
    prune(serde_json::to_value(animation).expect("序列化 animation"))
}

struct Case {
    id: String,
    animation: Animation,
    /// `None` = use `LOCAL_GRID`; `Some` = explicit progress points (used together with `dur = PROGRESS_DUR`).
    progress: Option<ProgressKind>,
}

#[derive(Clone, Copy)]
enum ProgressKind {
    Enter,
    Exit,
}

fn case_json(case: &Case) -> Value {
    let mut samples = Vec::new();
    match case.progress {
        None => {
            for offset in LOCAL_GRID {
                let time = START + offset;
                samples.push(json!({
                    "local": offset,
                    "t": time,
                    "pose": pose_json(resolve_animation_pose(
                        Some(&case.animation),
                        START,
                        Some(END),
                        PROJECT_END,
                        time,
                        FPS,
                    )),
                }));
            }
        }
        Some(kind) => {
            for progress in PROGRESS_POINTS {
                let time = match kind {
                    ProgressKind::Enter => START + progress * PROGRESS_DUR,
                    ProgressKind::Exit => END - PROGRESS_DUR + progress * PROGRESS_DUR,
                };
                samples.push(json!({
                    "progress": progress,
                    "t": time,
                    "pose": pose_json(resolve_animation_pose(
                        Some(&case.animation),
                        START,
                        Some(END),
                        PROJECT_END,
                        time,
                        FPS,
                    )),
                }));
            }
        }
    }
    json!({
        "id": case.id,
        "animation": animation_json(&case.animation),
        "summary": summary_json(&case.animation),
        "samples": samples,
    })
}

/// All golden cases. The order is the fixture order; any change shows up in the diff.
fn cases() -> Vec<Case> {
    let mut cases = Vec::new();

    // ① Progress group: explicit dur=0.4 / delay=0, progress 0/25/50/75/100% × intensity.
    for preset in ENTER_PRESETS {
        for intensity in INTENSITIES {
            let mut enter = with_intensity(slot(preset), *intensity);
            enter.dur = Some(PROGRESS_DUR);
            enter.delay = Some(0.0);
            cases.push(Case {
                id: format!("progress/enter/{preset}@i{intensity}"),
                // exit explicitly set to none: observe only the entrance curve, so that a mirrored exit does not get mixed in.
                animation: animation(Some(enter), Some(slot("none")), None),
                progress: Some(ProgressKind::Enter),
            });
        }
    }
    for preset in EXIT_PRESET_IDS {
        for intensity in INTENSITIES {
            let mut exit = with_intensity(slot(preset), *intensity);
            exit.dur = Some(PROGRESS_DUR);
            exit.delay = Some(0.0);
            cases.push(Case {
                id: format!("progress/exit/{preset}@i{intensity}"),
                animation: animation(None, Some(exit), None),
                progress: Some(ProgressKind::Exit),
            });
        }
    }

    // ② Entrance with default duration plus derived mirrored exit (exit absent → derived via effective_exit).
    for preset in ENTER_PRESETS {
        cases.push(Case {
            id: format!("default/enterWithMirroredExit/{preset}"),
            animation: animation(Some(slot(preset)), None, None),
            progress: None,
        });
    }

    // ③ Explicit exit with default duration (enter absent).
    for preset in EXIT_PRESET_IDS {
        cases.push(Case {
            id: format!("default/explicitExit/{preset}"),
            animation: animation(None, Some(slot(preset)), None),
            progress: None,
        });
    }

    // ④ An id written into the exit slot that has no exit recipe: there should be no exit at all.
    for preset in EXIT_ONLY_IN_SCHEMA {
        cases.push(Case {
            id: format!("default/exitWithoutRecipe/{preset}"),
            animation: animation(Some(slot("fade")), Some(slot(preset)), None),
            progress: None,
        });
    }

    // ⑤ An explicit exit=none blocks the mirror derivation.
    cases.push(Case {
        id: "default/explicitNoneBlocksMirror/rise".to_owned(),
        animation: animation(Some(slot("rise")), Some(slot("none")), None),
        progress: None,
    });
    // With enter=none there is neither an entrance nor a mirrored exit.
    cases.push(Case {
        id: "default/enterNone".to_owned(),
        animation: animation(Some(slot("none")), None, None),
        progress: None,
    });

    // ⑥ Loop: enter and exit fixed to fade, observing the loop and envelope of the idle segment;
    //    jitter additionally covers the default seed(17), an explicit 17, and 42.
    let mut loop_slots: Vec<(String, AnimationSlot)> = Vec::new();
    for preset in LOOP_PRESETS {
        loop_slots.push(((*preset).to_owned(), slot(preset)));
    }
    for seed in [17_u64, 42] {
        let mut jitter = slot("jitter");
        jitter.seed = Some(seed);
        loop_slots.push((format!("jitter#seed{seed}"), jitter));
    }
    for (label, loop_slot) in loop_slots {
        for intensity in INTENSITIES {
            cases.push(Case {
                id: format!("loop/{label}@i{intensity}"),
                animation: animation(
                    Some(slot("fade")),
                    Some(slot("fade")),
                    Some(with_intensity(loop_slot.clone(), *intensity)),
                ),
                progress: None,
            });
        }
    }
    // Loop only, with no entrance or exit: the idle segment is the whole lifetime.
    cases.push(Case {
        id: "loop/floatOnly".to_owned(),
        animation: animation(None, None, Some(slot("float"))),
        progress: None,
    });

    cases
}

/// ADR-M10: the stage at 60 fps and the export project's fps use two different time grids, and `quantize_time`
/// rounds down, so the same instant lands on different poses on the two grids. Here the difference is pinned down as data.
fn fps_quantization() -> Value {
    let animation = animation(Some(slot("rise")), None, Some(slot("float")));
    let probes = [1.0, 1.01, 1.025, 1.04, 1.1, 1.2599, 2.5, 3.0, 4.995];
    let rows = probes
        .iter()
        .map(|time| {
            let at30 = resolve_animation_pose(
                Some(&animation),
                START,
                Some(END),
                PROJECT_END,
                *time,
                30.0,
            );
            let at60 = resolve_animation_pose(
                Some(&animation),
                START,
                Some(END),
                PROJECT_END,
                *time,
                60.0,
            );
            json!({
                "t": time,
                "quantized30": (time * 30.0 + 1e-9).floor() / 30.0,
                "quantized60": (time * 60.0 + 1e-9).floor() / 60.0,
                "fps30": pose_json(at30),
                "fps60": pose_json(at60),
                "identical": at30 == at60,
            })
        })
        .collect::<Vec<_>>();
    json!({
        "note": "ADR-M10：舞台 60 fps 与导出项目 fps 的量化差异基线；阶段 1 统一到项目 fps 后 fps60 行按预期变化。",
        "animation": animation_json(&animation),
        "window": {"start": START, "end": END, "projectEnd": PROJECT_END},
        "rows": rows,
    })
}

#[test]
fn timeline_poses_match_golden() {
    let cases = cases().iter().map(case_json).collect::<Vec<_>>();
    let document = json!({
        "note": "Timeline enter/exit/loop preset 的 AnimationPose 语义基线（阶段 0）。",
        "generator": "cargo test -p ccut-timeline --test motion_baseline（CCUT_UPDATE_GOLDEN=1 重生成）",
        "window": {"start": START, "end": END, "projectEnd": PROJECT_END, "fps": FPS},
        "enterPresets": ENTER_PRESETS,
        "exitPresets": EXIT_PRESET_IDS,
        "exitLegacyPresets": EXIT_ONLY_IN_SCHEMA,
        "loopPresets": LOOP_PRESETS,
        "localGrid": LOCAL_GRID,
        "progressDur": PROGRESS_DUR,
        "progressPoints": PROGRESS_POINTS,
        "intensities": INTENSITIES,
        "cases": cases,
        "fpsQuantization": fps_quantization(),
    });
    assert_golden("timeline-poses.json", &document);
}

// ── Text parts ────────────────────────────────────────────────────────

const TEXT_SAMPLES: &[(&str, &str)] = &[
    ("empty", ""),
    ("single", "a"),
    ("english", "Hello world"),
    ("chinese", "你好，世界"),
    ("mixed", "Hello 世界 mix"),
    ("emoji", "ok 👍🏽 go 🇨🇳"),
    ("combining", "cafe\u{301} test"),
    ("padded", "  spaced   out  "),
    ("newline", "line one\nline two"),
];

fn ranges_json(text: &str, unit: AnimationPartUnit) -> Value {
    Value::Array(
        split_animation_parts(text, unit)
            .into_iter()
            .map(|range| {
                json!({
                    "start": range.start,
                    "end": range.end,
                    "text": &text[range.clone()],
                })
            })
            .collect(),
    )
}

/// Each sample records only the container and parts: `ranges` is constant within the same case, so it is recorded once at the case level
/// (for the full split see `splits`).
fn frame_json(frame: &TextAnimationFrame) -> Value {
    json!({
        "container": pose_json(frame.container),
        "parts": frame.parts.iter().map(|part| json!({
            "index": part.index,
            "opacity": part.opacity,
            "dx": part.dx,
            "dy": part.dy,
        })).collect::<Vec<_>>(),
    })
}

fn frame_ranges_json(frame: &TextAnimationFrame, text: &str) -> Value {
    Value::Array(
        frame
            .ranges
            .iter()
            .map(|range| {
                json!({
                    "start": range.start,
                    "end": range.end,
                    "text": &text[range.clone()],
                })
            })
            .collect(),
    )
}

/// Text cascade sampling instants: dense within the entrance window (the cascade unfolding), a point just after the window (settling back to the container
/// pose), and the exit segment (mirrored exit).
const TEXT_TIMES: &[f64] = &[
    1.0, 1.03, 1.07, 1.12, 1.18, 1.3, 1.5, 1.9, 2.5, 4.6, 4.9, 5.0,
];

#[test]
fn timeline_text_parts_match_golden() {
    let mut splits = Vec::new();
    for (label, text) in TEXT_SAMPLES {
        splits.push(json!({
            "id": label,
            "text": text,
            "byteLen": text.len(),
            "char": ranges_json(text, AnimationPartUnit::Char),
            "word": ranges_json(text, AnimationPartUnit::Word),
        }));
    }

    let mut frames = Vec::new();
    for preset in ["typewriter", "riseWords"] {
        for (label, text) in TEXT_SAMPLES {
            for intensity in INTENSITIES {
                let animation =
                    animation(Some(with_intensity(slot(preset), *intensity)), None, None);
                let mut ranges = Value::Null;
                let mut unit = Value::Null;
                let samples = TEXT_TIMES
                    .iter()
                    .map(|time| {
                        let frame = resolve_text_animation(
                            Some(&animation),
                            START,
                            Some(END),
                            PROJECT_END,
                            *time,
                            FPS,
                            text,
                        );
                        let here = frame_ranges_json(&frame, text);
                        let here_unit = frame
                            .unit
                            .map_or(Value::Null, |unit| Value::from(format!("{unit:?}")));
                        if !frame.parts.is_empty() {
                            // unit and ranges are constant during the cascade: recorded once at the case level.
                            if ranges.is_null() {
                                ranges = here;
                                unit = here_unit;
                            } else {
                                assert_eq!(
                                    ranges, here,
                                    "{preset}/{label} 的 ranges 在级联期间漂移"
                                );
                                assert_eq!(unit, here_unit);
                            }
                        }
                        json!({"t": time, "frame": frame_json(&frame)})
                    })
                    .collect::<Vec<_>>();
                frames.push(json!({
                    "id": format!("{preset}/{label}@i{intensity}"),
                    "preset": preset,
                    "text": text,
                    "intensity": intensity,
                    "unit": unit,
                    "ranges": ranges,
                    "samples": samples,
                }));
            }
        }
    }

    // stagger and staggerFrom variants: the cascade order is part of the part semantics.
    let mut stagger = Vec::new();
    for from in [None, Some("start"), Some("end"), Some("center")] {
        let mut enter = slot("riseWords");
        enter.stagger = Some(0.08);
        enter.stagger_from = from.map(str::to_owned);
        let animation = animation(Some(enter), None, None);
        let text = "one two three four five";
        let samples = [1.0, 1.15, 1.3, 1.5, 1.8]
            .iter()
            .map(|time| {
                let frame = resolve_text_animation(
                    Some(&animation),
                    START,
                    Some(END),
                    PROJECT_END,
                    *time,
                    FPS,
                    text,
                );
                json!({
                    "t": time,
                    "ranges": frame_ranges_json(&frame, text),
                    "frame": frame_json(&frame),
                })
            })
            .collect::<Vec<_>>();
        stagger.push(json!({
            "id": format!("riseWords/staggerFrom={}", from.unwrap_or("<absent>")),
            "staggerFrom": from,
            "text": text,
            "samples": samples,
        }));
    }

    // Non-cascade presets use the whole container: confirms that resolve_text_animation degenerates to resolve_animation_pose.
    let mut container = Vec::new();
    for preset in ["fade", "pop", "wipe"] {
        let animation = animation(Some(slot(preset)), None, None);
        let text = "Hello world";
        let samples = TEXT_TIMES
            .iter()
            .map(|time| {
                let frame = resolve_text_animation(
                    Some(&animation),
                    START,
                    Some(END),
                    PROJECT_END,
                    *time,
                    FPS,
                    text,
                );
                let pose = resolve_animation_pose(
                    Some(&animation),
                    START,
                    Some(END),
                    PROJECT_END,
                    *time,
                    FPS,
                );
                assert_eq!(
                    frame.container, pose,
                    "{preset} 非级联，容器 pose 必须与 resolve_animation_pose 相同"
                );
                json!({"t": time, "frame": frame_json(&frame)})
            })
            .collect::<Vec<_>>();
        container.push(json!({"id": format!("container/{preset}"), "samples": samples}));
    }

    let document = json!({
        "note": "typewriter / riseWords 的 part 切分与逐 part pose 语义基线（阶段 0）。",
        "generator": "cargo test -p ccut-timeline --test motion_baseline（CCUT_UPDATE_GOLDEN=1 重生成）",
        "window": {"start": START, "end": END, "projectEnd": PROJECT_END, "fps": FPS},
        "times": TEXT_TIMES,
        "splits": splits,
        "frames": frames,
        "stagger": stagger,
        "containerFallback": container,
    });
    assert_golden("timeline-text-parts.json", &document);
}

// ── Out-of-order sampling consistency ───────────────────────────────────

/// Deterministic permutation with a fixed seed (splitmix64 → Fisher-Yates), without adding a rand dependency.
fn shuffled(len: usize, mut seed: u64) -> Vec<usize> {
    let mut next = move || {
        seed = seed.wrapping_add(0x9E37_79B9_7F4A_7C15);
        let mut z = seed;
        z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
        z ^ (z >> 31)
    };
    let mut order = (0..len).collect::<Vec<_>>();
    for index in (1..len).rev() {
        let pick = (next() % (index as u64 + 1)) as usize;
        order.swap(index, pick);
    }
    order
}

fn probe_times() -> Vec<f64> {
    // Covers inside and outside the window, including intra-frame offsets and endpoints.
    let mut times = Vec::new();
    let mut frame = -6_i32;
    while frame <= 186 {
        times.push(START + f64::from(frame) / FPS);
        frame += 1;
    }
    for extra in [0.9999, 1.0001, 2.51234, 3.33333, 4.99999, 5.5, 9.9] {
        times.push(extra);
    }
    times
}

#[test]
fn resolve_animation_pose_is_order_independent() {
    let times = probe_times();
    let order = shuffled(times.len(), 0x5EED_1234_ABCD_0001);
    assert_ne!(
        order,
        (0..times.len()).collect::<Vec<_>>(),
        "置换必须真乱序"
    );
    for case in cases() {
        let sorted = times
            .iter()
            .map(|time| {
                resolve_animation_pose(
                    Some(&case.animation),
                    START,
                    Some(END),
                    PROJECT_END,
                    *time,
                    FPS,
                )
            })
            .collect::<Vec<_>>();
        let mut shuffled_out = vec![AnimationPose::IDENTITY; times.len()];
        for index in &order {
            shuffled_out[*index] = resolve_animation_pose(
                Some(&case.animation),
                START,
                Some(END),
                PROJECT_END,
                times[*index],
                FPS,
            );
        }
        for (index, (a, b)) in sorted.iter().zip(shuffled_out.iter()).enumerate() {
            assert!(
                bitwise_eq(*a, *b),
                "{} 在 t={} 上顺序/乱序采样不一致：{a:?} vs {b:?}",
                case.id,
                times[index]
            );
        }
    }
}

fn bitwise_eq(a: AnimationPose, b: AnimationPose) -> bool {
    let bits = |pose: AnimationPose| {
        (
            pose.opacity.to_bits(),
            pose.dx.to_bits(),
            pose.dy.to_bits(),
            pose.scale_x.to_bits(),
            pose.scale_y.to_bits(),
            pose.rotation.to_bits(),
            pose.blur.to_bits(),
            pose.reveal.map(f64::to_bits),
        )
    };
    bits(a) == bits(b)
}

#[test]
fn resolve_text_animation_is_order_independent() {
    let times = probe_times();
    let order = shuffled(times.len(), 0x5EED_1234_ABCD_0002);
    for preset in ["typewriter", "riseWords", "fade"] {
        for (_, text) in TEXT_SAMPLES {
            let animation = animation(Some(slot(preset)), None, None);
            let sample = |time: f64| {
                resolve_text_animation(
                    Some(&animation),
                    START,
                    Some(END),
                    PROJECT_END,
                    time,
                    FPS,
                    text,
                )
            };
            let sorted = times.iter().map(|time| sample(*time)).collect::<Vec<_>>();
            let mut out: BTreeMap<usize, TextAnimationFrame> = BTreeMap::new();
            for index in &order {
                out.insert(*index, sample(times[*index]));
            }
            for (index, expected) in sorted.iter().enumerate() {
                let actual = &out[&index];
                let at = times[index];
                assert_eq!(
                    expected.unit, actual.unit,
                    "{preset} 在 t={at} 上 unit 不一致"
                );
                assert_eq!(
                    expected.ranges, actual.ranges,
                    "{preset} 在 t={at} 上 ranges 不一致"
                );
                assert!(
                    bitwise_eq(expected.container, actual.container),
                    "{preset} 在 t={at} 上容器 pose 不一致"
                );
                assert_eq!(expected.parts.len(), actual.parts.len());
                for (a, b) in expected.parts.iter().zip(actual.parts.iter()) {
                    assert_eq!(a.index, b.index);
                    assert_eq!(a.opacity.to_bits(), b.opacity.to_bits(), "t={at}");
                    assert_eq!(a.dx.to_bits(), b.dx.to_bits(), "t={at}");
                    assert_eq!(a.dy.to_bits(), b.dy.to_bits(), "t={at}");
                }
            }
        }
    }
}

#[test]
fn golden_covers_every_declared_preset() {
    let cases = cases();
    let ids = cases
        .iter()
        .map(|case| case.id.as_str())
        .collect::<Vec<_>>();
    assert_eq!(
        ids.len(),
        ids.iter().collect::<std::collections::BTreeSet<_>>().len(),
        "case id 必须唯一"
    );
    for preset in ENTER_PRESETS {
        assert!(
            ids.iter()
                .any(|id| id.starts_with(&format!("progress/enter/{preset}@"))),
            "缺 enter preset 覆盖：{preset}"
        );
    }
    for preset in LOOP_PRESETS {
        assert!(
            ids.iter()
                .any(|id| id.starts_with(&format!("loop/{preset}@"))),
            "缺 loop preset 覆盖：{preset}"
        );
    }
    // The set difference between the exit-recipe table and the schema declaration must be explicitly covered, to avoid silent drift.
    for preset in EXIT_PRESET_IDS {
        assert!(
            ids.iter()
                .any(|id| id.starts_with(&format!("progress/exit/{preset}@")))
        );
    }
}

